/**
 * Validate a date string in YYYY-MM-DD format (UTC).
 * @param {string} dateString
 * @returns {boolean}
 */
export function isValidDate(dateString) {
  if (typeof dateString !== 'string') return false;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateString)) return false;

  const date = new Date(dateString + 'T00:00:00Z');
  if (isNaN(date.getTime())) return false;

  const [year, month, day] = dateString.split('-').map(Number);
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/**
 * Add n days to a date string (YYYY-MM-DD, UTC).
 * @param {string} dateString
 * @param {number} days
 * @returns {string}
 */
export function addDays(dateString, days) {
  const date = new Date(dateString + 'T00:00:00Z');
  date.setUTCDate(date.getUTCDate() + days);
  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, '0');
  const day = String(date.getUTCDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

/**
 * Calculate the difference in whole days between two dates (b minus a, in UTC).
 * @param {string} dateStringA
 * @param {string} dateStringB
 * @returns {number}
 */
export function daysBetween(dateStringA, dateStringB) {
  const dateA = new Date(dateStringA + 'T00:00:00Z');
  const dateB = new Date(dateStringB + 'T00:00:00Z');
  const diffMs = dateB.getTime() - dateA.getTime();
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

/** Every error code the project returns, with a one-line message. Codes are UPPER_SNAKE_CASE. */
export const ERRORS = {
  AMOUNT_INVALID: 'Amount must be a whole, positive number of cents.',
  CUSTOMER_INVALID: 'A customer needs an id, a name and a valid email.',
  CUSTOMER_NOT_FOUND: 'No customer with that id.',
  DATE_INVALID: 'Issue date must be in YYYY-MM-DD format.',
  DISCOUNT_INVALID: 'Discount must be a number between 0 and 100.',
  LINE_NOT_FOUND: 'No line with that SKU on the invoice.',
  NO_LINES: 'An invoice must have at least one line.',
  NOT_DRAFT: 'Only draft invoices can be edited.',
  NOT_ISSUED: 'Only issued or partially paid invoices can receive payments.',
  OVERPAYMENT: 'Payment exceeds the amount still owed.',
  QTY_INVALID: 'Quantity must be a positive integer.',
  UNKNOWN_SKU: 'No product with that SKU in the catalogue.',
};

/**
 * The message for an error code.
 * @param {string} code
 * @returns {string}
 */
export function message(code) {
  return ERRORS[code] ?? 'Unknown error.';
}

