    ],
  }).value;

  const totals = invoiceTotals(invoice);
  const subtotal = 5 * 9500 + 3 * 6000;
  const discount = 4750 + 3600;
  const line1Discounted = 47500 - 4750;
  const line2Discounted = 18000 - 3600;
  const vat = Math.round(line1Discounted * 21 / 100) + Math.round(line2Discounted * 21 / 100);
