  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const totals = invoiceTotals(invoice);
  const subtotal = 95000;
  const discount = Math.round(95000 * 5 / 100);
  const discountedAmount = subtotal - discount;
  const vat = Math.round(discountedAmount * 21 / 100);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal - discount + vat);
});

